# 定義一個函式，用來在 OLED 顯示單張圖片
def draw_image(oled, img):
    # 清空整個畫面（oled.fill(0) → 將整個畫面填滿 0，顯示黑色）
    oled.fill(0)
    
    # 檢查傳入的圖片資料是否正確
    # SSD1306 128x64 OLED 解析度 = 128*64/8 = 1024 bytes
    if len(img) != 1024:
        # 如果長度不對，丟出錯誤，提醒使用者
        raise ValueError("圖像必須是 1024 bytes")
    
    # 將圖片資料直接複製到 OLED 的緩衝區
    # oled.buffer 是一個 bytearray，儲存即將顯示的畫面資料
    oled.buffer[:] = bytes(img)
    
    # 將緩衝區資料送到 OLED 顯示器上
    oled.show()

# 呼叫剛才定義的函式，顯示 IMG04 圖片
draw_image(oled, IMG04)

# 暫停程式 2 秒，讓畫面維持可見
time.sleep(2)


# 建立一個動畫圖片列表，依序放入各張圖片
images = [IMG01, IMG02, IMG03, IMG04]

# 定義一個函式，用來依序顯示列表中的圖片（動畫效果）
def show_image():
    # 逐張讀取 images 列表中的圖片
    for img in images:
        # 顯示單張圖片
        draw_image(oled, img)
        # 暫停 0.2 秒，讓畫面維持可見，形成動畫
        time.sleep(0.2)
        # 顯示完一張圖後，釋放垃圾記憶體，避免 ESP32 RAM 堆積
        gc.collect()

# 呼叫函式開始顯示動畫
show_image()


